'use client'

import { Suspense, useMemo } from 'react'

import { useLibraries, useSetupCommands } from '@/core/hooks'
import type { LibraryData } from '@/core/types/library.type'
import {
  buildGatewayMcpSnapshot,
  buildInstallationSnapshotsForLibrary,
  CONSUMER_TECHNOLOGIES,
  PACKAGE_MANAGER_MAP,
} from '@/core/utils/installation'
import { GATEWAY_WEBSOCKET_CHANNEL_PATH, MCP_ENDPOINT_PATH } from '@/core/vision-core.const'

import { InstallationGatewayMcpSection } from './InstallationGatewayMcpSection'
import { InstallationLibrarySection, type LibraryInstallationMatrix } from './InstallationLibrarySection'

import styles from './page.module.scss'

function InstallationOverview() {
  const {
    libraries,
    guid,
    registry,
    gsmuEndpoint,
    gatewayPath,
    gatewayWsPort,
    gatewayMcpPort,
    projectName,
    isSecured,
    isLoading: isLibrariesLoading,
    isError: isLibrariesError,
    error: librariesError,
  } = useLibraries()

  const {
    technologySetupCommands,
    isLoading: isSetupCommandsLoading,
    isError: isSetupCommandsError,
    error: setupCommandsError,
  } = useSetupCommands()

  const gatewayParams = useMemo(
    () => ({
      technologySetupCommands,
      gatewayPath,
      gatewayWsPort,
      guid,
      registryPath: registry,
      gsmuEndpoint,
      isSecured,
    }),
    [technologySetupCommands, gatewayPath, gatewayWsPort, guid, registry, gsmuEndpoint, isSecured]
  )

  const matrices = useMemo(
    (): LibraryInstallationMatrix[] =>
      Object.values(libraries).map((libraryData: LibraryData) => ({
        libraryId: libraryData.id,
        libraryName: libraryData.name,
        runtimeName: libraryData.runtimeName,
        suggestedConsumer: PACKAGE_MANAGER_MAP[libraryData.runtimeName],
        snapshots: buildInstallationSnapshotsForLibrary(libraryData, gatewayParams),
      })),
    [libraries, gatewayParams]
  )

  const gatewayMcpSnapshot = useMemo(
    () =>
      buildGatewayMcpSnapshot({
        gatewayPath,
        gatewayMcpPort,
        isSecured,
        projectName,
      }),
    [gatewayPath, gatewayMcpPort, isSecured, projectName]
  )

  const isLoading = isLibrariesLoading || isSetupCommandsLoading
  const isError = isLibrariesError || isSetupCommandsError
  const error = librariesError ?? setupCommandsError

  if (isLoading) {
    return <p className={styles.status}>Loading hosted modules and setup commands…</p>
  }

  if (isError) {
    return (
      <p className={styles.statusError}>
        Failed to load gateway data{error instanceof Error ? `: ${error.message}` : '.'}
      </p>
    )
  }

  return (
    <main className={styles.page}>
      <header className={styles.header}>
        <h1>Installation overview</h1>
        <p className={styles.subtitle}>
          Install commands from gateway routes (/npm, /maven, /nuget, /pypi, /packagist, /rubygems), gateway MCP client
          config, and configuration snippets for every hosted module and consumer package manager.
        </p>

        <dl className={styles.inputs}>
          <div>
            <dt>Modules</dt>
            <dd>
              <code>{matrices.length}</code>
            </dd>
          </div>
          <div>
            <dt>Setup command routes loaded</dt>
            <dd>
              <code>{Object.keys(technologySetupCommands).length}</code> / <code>{CONSUMER_TECHNOLOGIES.length}</code>
            </dd>
          </div>
          <div>
            <dt>Project</dt>
            <dd>
              <code>{projectName || '—'}</code>
            </dd>
          </div>
          <div>
            <dt>Registry path</dt>
            <dd>
              <code>{registry || '—'}</code>
            </dd>
          </div>
          <div>
            <dt>Guid tier</dt>
            <dd>
              <code>{guid || '—'}</code>
            </dd>
          </div>
          <div>
            <dt>GSMU endpoint</dt>
            <dd>
              <code>{gsmuEndpoint || '—'}</code>
            </dd>
          </div>
          <div>
            <dt>Gateway</dt>
            <dd>
              <code>
                {isSecured ? 'wss' : 'ws'}://{gatewayPath}
                {gatewayWsPort ? `:${gatewayWsPort}` : ''}/{GATEWAY_WEBSOCKET_CHANNEL_PATH}
              </code>
            </dd>
          </div>
          <div>
            <dt>MCP</dt>
            <dd>
              <code>
                {isSecured ? 'https' : 'http'}://{gatewayPath}
                {gatewayMcpPort ? `:${gatewayMcpPort}` : ''}/{MCP_ENDPOINT_PATH}
              </code>
            </dd>
          </div>
        </dl>
      </header>

      <InstallationGatewayMcpSection snapshot={gatewayMcpSnapshot} />

      {matrices.length === 0 ? (
        <p className={styles.status}>No hosted modules found on this gateway.</p>
      ) : (
        matrices.map((matrix) => <InstallationLibrarySection key={matrix.libraryId} matrix={matrix} />)
      )}
    </main>
  )
}

export default function InstallationPage() {
  return (
    <Suspense fallback={<p className={styles.status}>Loading…</p>}>
      <InstallationOverview />
    </Suspense>
  )
}
