import { CodeSnippet, CodeSnippetVariant } from '@graftcode/design-system'

import { getCodeSnippetLanguage, TECHNOLOGY_SETUP_MAPPING } from '@/core/config/technologies'
import { formatCodeSnippetCalls } from '@/core/utils/builder/formatCodeSnippetCalls.builder'
import type { InstallationSnapshot } from '@/core/utils/installation'

import styles from './InstallationConsumerSection.module.scss'

interface InstallationConsumerSectionProps {
  snapshot: InstallationSnapshot
  consumerLabel: string
  isSuggested: boolean
}

export function InstallationConsumerSection({
  snapshot,
  consumerLabel,
  isSuggested,
}: InstallationConsumerSectionProps) {
  const language = getCodeSnippetLanguage(snapshot.consumerTechnology)

  const setupCommands = Object.entries(snapshot.setupCommandMap).map(([label, code]) => ({
    label,
    code: formatCodeSnippetCalls(code),
  }))

  const configurationBlocks: Array<{ label: string; code: string; language: string }> = []
  const configurationMap = Object.fromEntries(
    Object.entries(snapshot.configurationMap).map(([key, value]) => [key, formatCodeSnippetCalls(value)])
  )

  if (configurationMap['In Code']) {
    configurationBlocks.push({ label: 'In code', code: configurationMap['In Code'], language })
  }
  if (configurationMap.TXT) {
    configurationBlocks.push({ label: 'Config file (.txt)', code: configurationMap.TXT, language: 'plaintext' })
  }
  if (configurationMap.JSON) {
    configurationBlocks.push({ label: 'Config file (.json)', code: configurationMap.JSON, language: 'json' })
  }
  if (configurationMap.YAML) {
    configurationBlocks.push({ label: 'Config file (.yaml)', code: configurationMap.YAML, language: 'yaml' })
  }
  if (configurationMap['ENV variable']) {
    configurationBlocks.push({
      label: 'ENV var',
      code: configurationMap['ENV variable'],
      language: 'plaintext',
    })
  }

  const importCode = formatCodeSnippetCalls(snapshot.importCode)
  const gatewayRoute =
    TECHNOLOGY_SETUP_MAPPING.find((entry) => entry.id === snapshot.consumerTechnology)?.path ??
    snapshot.consumerTechnology

  return (
    <article
      className={styles.consumer}
      id={`${snapshot.libraryId}-${snapshot.consumerTechnology}`}
      data-suggested={isSuggested || undefined}
    >
      <h3 className={styles.consumerTitle}>
        {consumerLabel}
        {isSuggested && <span className={styles.suggestedBadge}>Suggested for this runtime</span>}
      </h3>

      <dl className={styles.summary}>
        <div>
          <dt>Registry URL</dt>
          <dd>
            <code>{snapshot.registryUrl || '—'}</code>
          </dd>
        </div>
        <div>
          <dt>publishId</dt>
          <dd>
            <code>{snapshot.graftNames.publishId}</code>
          </dd>
        </div>
        <div>
          <dt>graftName</dt>
          <dd>
            <code>{snapshot.graftNames.graftName}</code>
          </dd>
        </div>
        {snapshot.consumerTechnology === 'maven' && (
          <div>
            <dt>Maven coords</dt>
            <dd>
              <code>
                {snapshot.graftNames.mavenGroupId}:{snapshot.graftNames.mavenArtifactId}
              </code>
            </dd>
          </div>
        )}
      </dl>

      <h4 className={styles.blockTitle}>Installation</h4>
      {setupCommands.length === 0 ? (
        <p className={styles.empty}>No setup command returned from gateway /{gatewayRoute}.</p>
      ) : (
        setupCommands.map(({ label, code }) => (
          <div key={label} className={styles.block}>
            <p className={styles.blockLabel}>{label}</p>
            <CodeSnippet code={code} language={language} contentVariant={CodeSnippetVariant.Terminal} />
          </div>
        ))
      )}

      <h4 className={styles.blockTitle}>Configuration</h4>
      {configurationBlocks.map(({ label, code, language: blockLanguage }) => (
        <div key={label} className={styles.block}>
          <p className={styles.blockLabel}>{label}</p>
          <CodeSnippet code={code} language={blockLanguage} contentVariant={CodeSnippetVariant.Terminal} />
        </div>
      ))}

      <h4 className={styles.blockTitle}>Import</h4>
      <div className={styles.block}>
        <CodeSnippet code={importCode} language={language} contentVariant={CodeSnippetVariant.Terminal} />
      </div>
    </article>
  )
}
