import { Runtime } from '@/core/enums/runtime.enum'
import { CONSUMER_TECHNOLOGIES, type InstallationSnapshot } from '@/core/utils/installation'
import { HOSTED_RUNTIME_LABEL } from '@/core/vision-core.const'

import { InstallationConsumerSection } from './InstallationConsumerSection'

import styles from './InstallationLibrarySection.module.scss'

export interface LibraryInstallationMatrix {
  libraryId: string
  libraryName: string
  runtimeName: Runtime
  suggestedConsumer?: string
  snapshots: InstallationSnapshot[]
}

interface InstallationLibrarySectionProps {
  matrix: LibraryInstallationMatrix
}

export function InstallationLibrarySection({ matrix }: InstallationLibrarySectionProps) {
  const runtimeLabel = HOSTED_RUNTIME_LABEL[matrix.runtimeName] ?? matrix.runtimeName
  const consumerLabels = Object.fromEntries(CONSUMER_TECHNOLOGIES.map(({ id, label }) => [id, label]))

  return (
    <section className={styles.section} id={matrix.libraryId}>
      <h2 className={styles.title}>{matrix.libraryName}</h2>
      <p className={styles.meta}>
        Hosted on {runtimeLabel}
        {matrix.suggestedConsumer && (
          <>
            {' '}
            · suggested consumer <code>{matrix.suggestedConsumer}</code>
          </>
        )}
      </p>

      <div className={styles.consumers}>
        {matrix.snapshots.map((snapshot) => (
          <InstallationConsumerSection
            key={snapshot.consumerTechnology}
            snapshot={snapshot}
            consumerLabel={consumerLabels[snapshot.consumerTechnology] ?? snapshot.consumerTechnology}
            isSuggested={snapshot.consumerTechnology === matrix.suggestedConsumer}
          />
        ))}
      </div>
    </section>
  )
}
